from taf.analyzer.base import LogEntry


class Ims2ChangesetLogEntry(LogEntry):

    def __init__(self, updates, removals, **kwargs):
        super(Ims2ChangesetLogEntry, self).__init__(**kwargs)
        self.updates = updates
        self.removals = removals

    def __repr__(self):
        return (
            "Ims2ChangesetLogEntry("
            "timestamp={timestamp!r}, "
            "updates={updates!r}, "
            "removals={removals!r})".format(
                timestamp=self.timestamp,
                updates=self.updates,
                removals=self.removals))


class Ims2ResetLogEntry(LogEntry):
    def __repr__(self):
        return "Ims2ResetLogEntry(timestamp={timestamp!r})".format(
            timestamp=self.timestamp)
